import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"43、【夬】 乾下兌上","description":"周易尚氏學 - 43、【夬】 乾下兌上","frontmatter":{"title":"43、【夬】 乾下兌上","description":"周易尚氏學 - 43、【夬】 乾下兌上"},"headers":[],"relativePath":"classics/shangshi/048.md","filePath":"classics/shangshi/048.md"}'),s={name:"classics/shangshi/048.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_43、【夬】-乾下兌上" tabindex="-1">43、【夬】 乾下兌上 <a class="header-anchor" href="#_43、【夬】-乾下兌上" aria-label="Permalink to “43、【夬】 乾下兌上”">​</a></h1><p>王育雲。夾即古文塊字。按禮內則。右佩塊。釋文本又作決。詩小雅。決拾既飲是也。而夬決。故夬與決同。說文玉佩也。廣韻合同似環而有缺。夬乾為玉為圜。兌上缺。儼然塊形也。而決者絕也。左傳晉獻公賜太子申生塊。以示決絕。卦以五陽決一陰。故謂之夬也。歸藏以夬為規。規圜也。夬重乾。乾圜故為規。決亦圜。然上缺。是周易取象。與歸藏同而更切也。乾為王。伏艮為庭。一陰履五陽之上。故曰揚於王庭。兌口為號。厲危。孚號有厲者。言陰雖孚於陽。為陽所說。然窮處於上。須危厲自警也。兌口故曰告。兌為斧鉞。故曰戎。說文戎兵也。禮月令以習王戎。注弓殳矛戈戰。伏艮為邑。告自邑。不利即戎者。言一陰危處於上。告誡國人。不可妄動也。皆指上六言也。利有攸往。謂五。夬本陽息卦。五息而往則陰盡。夬者決也。決者絕也。陽決陰也。</p><p>彖曰。夬。決也。剛決柔也。健而說。決而和。揚於王庭。柔乘五剛也 孚號有後。其危乃光也。告自邑。不利即戎。所尚乃窮也。利有攸往。剛長乃終也。</p><p>下健上說。說故和。其危乃光者。危謂陰退。陰退則陽長。陽長故光。所尚乃窮。申不利即戎之故也。陽長乃終。終謂陰盡也。</p><p>象曰。澤上於天。夬。君子以施祿及下。居德則忌。</p><p>祿謂恩澤。澤在天上無用。故君子思以下施。乾為富。故為德。德得同。苟子禮論篇。貴始得之本也。注得當為德。居積也。下乾。二至四。三至五。皆乾。乾多故曰居德。居德則忌者。言蓄積大多。多藏厚亡。為人所忌也。象辭每相反以取義。此亦其一也。</p><p>初九。壯於前趾。往不勝為咎。</p><p>初震爻。震足故曰趾。震動故曰前趾。壯。傷也。陽遇陽得敵。故傷於前趾。故往不勝而有咎矣。趾荀作止。晁氏雲止古文。按說文有止無趾。止即足之象形字。加足者非也。</p><h3 id="象曰。不勝而往。咎也。" tabindex="-1">象曰。不勝而往。咎也。 <a class="header-anchor" href="#象曰。不勝而往。咎也。" aria-label="Permalink to “象曰。不勝而往。咎也。”">​</a></h3><p>前有重陽。所遇皆敵。不勝必矣。明知不勝而往。宜其有咎。</p><p>九二。惕號。莫夜有戎。勿恤。</p><p>乾為惕為言。故曰惕號。言有所警戒也。二應在五。五兌。兌為昧谷。故為莫為夜。兌為兵戎。故曰莫夜有戎。言有寇警也。然五不應二。故雖莫夜有戎。無憂也。乾為惕故為憂。舊解因不知勿恤之故何在。故用象皆誤。豈知隨象雲。君子以晌晦人宴息。晌晦即謂兌。然則兌為莫夜。易有明象。而兌五不應二。故雖有虛驚。實不足憂恐也。</p><h3 id="象曰。有戎勿恤。得中道也。乾為道。二中位。" tabindex="-1">象曰。有戎勿恤。得中道也。乾為道。二中位。 <a class="header-anchor" href="#象曰。有戎勿恤。得中道也。乾為道。二中位。" aria-label="Permalink to “象曰。有戎勿恤。得中道也。乾為道。二中位。”">​</a></h3><p>九三。壯於頂 有兇。君子決夬獨行。遇雨。若儒。有慍。無咎。</p><p>顧（左九）面顴也。三居下卦之上。故曰頒（左九）。而四五皆陽。故傷及於頎（左九）。傷頎（左九）故兇。乾為君子。承乘皆陽遇敵。故決夬獨行。而應在上。上兌為雨。故曰遇雨。曰若濡。濡。雨（下沾）溼也。乾為衣。衣濡故溫。然究為正應。亦無咎也。</p><h3 id="象曰。君子決夬。終無咎也。" tabindex="-1">象曰。君子決夬。終無咎也。 <a class="header-anchor" href="#象曰。君子決夬。終無咎也。" aria-label="Permalink to “象曰。君子決夬。終無咎也。”">​</a></h3><p>決夬獨行狀。三於四五雖遇敵。於卜獨有應。故曰終無咎。終謂上。</p><p>九四。臀無膚。其行次且。牽羊悔亡。聞言不信。</p><p>伏艮為膚。為尾。故為臀。臀尾閭也。艮伏故曰元膚。乾為行。承乘皆陽。失位。故其行次且。次且。馬雲卻行不前也。兌為羊。玉篇牽速也。娠九三雲。行未牽也。亦以奉為速。次且行緩。速則無悔。牽羊悔亡者。言四宜隨五。速進決陰。陰決則當位居五。故曰悔亡。舊說皆不知悔亡之故何在。則以牽字失詁也。兌為耳。故曰聞。乾為言為信。兌口亦為言。聞言不信者。兌言向外。與乾言相背。故不信也。兌耳象。鼎傳雲。翼而耳目聰明。目謂上離。耳謂互兌也。</p><h3 id="象曰。其行次且。位不當也。聞言不信。聰不明也。" tabindex="-1">象曰。其行次且。位不當也。聞言不信。聰不明也。 <a class="header-anchor" href="#象曰。其行次且。位不當也。聞言不信。聰不明也。" aria-label="Permalink to “象曰。其行次且。位不當也。聞言不信。聰不明也。”">​</a></h3><p>兌為耳。為黯昧。故曰不明。不明猶不審。俗所謂不清。虞氏以離目當之。非。</p><p>九五。覓陸決夬。中行無咎。</p><p>盂喜雲。覓陸獸名。夬有兌。兌為羊也。說文亦云崑山羊細角。諸家說此二字。人人異辭。獨孟氏於象密合。凡五皆謂中行。又決夬於羊行貌獨切。鄭虞等訓克陸為草屬。草焉有決夬之象哉。</p><h3 id="象曰。中行無咎。中未光也。" tabindex="-1">象曰。中行無咎。中未光也。 <a class="header-anchor" href="#象曰。中行無咎。中未光也。" aria-label="Permalink to “象曰。中行無咎。中未光也。”">​</a></h3><p>兌黯昧。故未光。</p><p>上六。無號。終有兇。</p><p>一陰在上。為陽所推。不能久也。兌為口故曰號。無號終有兇者。言不必號號眺（左口）。必消滅也。</p><h3 id="象曰。無號之兇。終不可長也。" tabindex="-1">象曰。無號之兇。終不可長也。 <a class="header-anchor" href="#象曰。無號之兇。終不可長也。" aria-label="Permalink to “象曰。無號之兇。終不可長也。”">​</a></h3><p>不可長。言不能長久。</p>',29)])])}const f=e(s,[["render",t]]);export{_ as __pageData,f as default};
